DROP TABLE IF EXISTS public.taipei_clothing_recycle_bins;

CREATE TABLE public.taipei_clothing_recycle_bins (
    source_city text,
    approval_id text PRIMARY KEY,
    category text,
    org_name text,
    org_type text,
    phone text,
    district text,
    village text,
    approved_location text,
    full_address text,
    approval_years text,
    note text,
    longitude double precision,
    latitude double precision
);

COPY public.taipei_clothing_recycle_bins (
    source_city, approval_id, category, org_name, org_type, phone, district,
    village, approved_location, full_address, approval_years, note, longitude, latitude
) FROM stdin;
